MOD = 10 ** 9 + 7
Factorial = [1] * 300000
for n in range(2, len(Factorial)):
	Factorial[n] = Factorial[n - 1] * n % MOD

def inv(n):
	return pow(n, MOD - 2, MOD)

def BinCoeff(n, k):
	if n < k or k < 0:
		return 0
	if n == k or k == 0:
		return 1
	return Factorial[n] * inv(Factorial[k] * Factorial[n - k]) % MOD

def solve2(x1, y1, x2, y2):
	return (BinCoeff(y2 + x2 - y1 - x1, y2 - y1) - BinCoeff(y2 + x2 - x1 - y1, y2 - x1 - 1)) % MOD

def solve(A):
	if A[0] != '?' and A[0] != '0':
		return 0
	if len(A) == 1:
		return 1
	B = {0: 0}
	for x in range(1, len(A)):
		if A[x] != '?':
			B[x - 1] = x - int(A[x])
	B[len(A) - 1] = len(A) - 1
	B_ind = []
	for b in B:
		if B[b] > b:
			return 0
		B_ind.append(b)
	B_ind.sort()
	for x in range(1, len(B_ind)):
		if B[B_ind[x]] < B[B_ind[x - 1]]:
			return 0
	result = 1
	for x in range(1, len(B_ind)):
		result = result * solve2(B_ind[x - 1] + 1, B[B_ind[x - 1]], B_ind[x], B[B_ind[x]]) % MOD
	return result
n = int(input())
A = input().split()
print(solve(A))
